import React, { useState } from 'react';


const commonDrugs = [
  // ── Analgesics / Antipyretics
  'Paracetamol 500mg',
  'Paracetamol 1000mg',
  'Ibuprofen 200mg',
  'Ibuprofen 400mg',
  'Aspirin 75mg',
  'Aspirin 300mg',
  'Diclofenac 50mg',
  'Tramadol 50mg',

  // ── Antibiotics
  'Amoxicillin 250mg',
  'Amoxicillin 500mg',
  'Amoxicillin/Clavulanate 625mg',
  'Ampicillin 250mg',
  'Ampicillin 500mg',
  'Azithromycin 250mg',
  'Azithromycin 500mg',
  'Ciprofloxacin 250mg',
  'Ciprofloxacin 500mg',
  'Doxycycline 100mg',
  'Erythromycin 250mg',
  'Erythromycin 500mg',
  'Metronidazole 200mg',
  'Metronidazole 400mg',
  'Metronidazole 500mg',
  'Cloxacillin 250mg',
  'Cloxacillin 500mg',
  'Tetracycline 250mg',
  'Trimethoprim/Sulfamethoxazole 480mg',

  // ── Antimalarials
  'Coartem (Artemether/Lumefantrine)',
  'Artesunate 50mg',
  'Artesunate 200mg',
